"use strict";(globalThis.webpackChunkgrc||=[]).push([[86918],{66904(e){e.exports=JSON.parse('{"citeKey":"najafi2022generalizedmodel","slug":"najafi-2022-generalized-model-3e33","title":"A Generalized Model For Modern Hierarchical Memory System","authors":["H. Najafi","X. Lu","J. Liu","X.-H. Sun"],"venue":"The 2022 Winter Simulation Conference (WSC), Singapore, December 11-14, 2022","type":"Conference","entryType":"inproceedings","date":"December, 2022","year":2022,"era":"iit","month":12,"doi":"10.1109/wsc57314.2022.10015298","abstract":"Memory system is critical to architecture design which can significantly impact application performance. Concurrent Average Memory Access Time (C-AMAT) is a model for analyzing and optimizing memory system performance using a recursive definition of the memory access latency along the memory hierarchy. The original C-AMAT model, however, does not provide the necessary granularity and flexibility for handling modern memory architectures with heterogeneous memory technologies and diverse system topology. We propose to augment C-AMAT to take into consideration the idiosyncrasies of individual cache/memory components as well as their topological arrangement in the memory architecture design. Through trace- based simulation, we validate the augmented model and examine the memory system performance with insight unavailable using the original C-AMAT model.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2022/najafi-2022-generalized-model-3e33.pdf"},"tags":["Hierarchical Memory System","C-AMAT","Optimization of Memory Architectures"],"_projectIds":["optmem"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["optmem"],"memberAuthors":["lu-xiaoyang","sun-xian-he"],"funding":[{"agency":"NSF","award":"CCF-2008000","projectId":"optmem"},{"agency":"NSF","award":"CCF-2008907","projectId":"optmem"}]}')}}]);